using FromZero;
using System.Text.Json;
static class PreparationChecks
{
 public static async Task Run(string root,Action<bool,string> check)
 {
  bool Reject(Action action){try{action();return false;}catch(Exception ex)when(ex is InvalidDataException or ArgumentException){return true;}}
  var job=PreparationPolicy.Create(new(){Apps=["firefox","vlc"]},"test-sid","C:\\FromZero.exe");check(job.Steps.First().Kind=="preflight"&&job.Steps.Last().Kind=="verify"&&job.Steps.FindIndex(s=>s.Kind=="backup")<job.Steps.FindIndex(s=>s.Kind=="drivers"),"Preparation orders preflight, backup, device drivers and final verification");
  check(job.Steps.Count(s=>s.Kind=="app")==2&&job.Steps.Count(s=>s.Kind=="package")==2,"Basic preparation installs only selected apps and two v14 architectures");
  var gaming=PreparationPolicy.Create(new(){Profile="gaming",GamingLibraries=true,Apps=["steam"]},"test-sid","C:\\FromZero.exe");check(gaming.Steps.Count(s=>s.Kind=="package")==13&&gaming.Steps.Count(s=>s.Kind=="app")==1,"Gaming preparation includes DirectX and twelve Visual C++ installers without unrelated apps");
  check(Reject(()=>PreparationPolicy.Create(new(){Apps=["shell"]},"sid","x"))&&Reject(()=>PreparationPolicy.Create(new(){Apps=["firefox","firefox"]},"sid","x")),"Unknown and duplicate installer IDs cannot enter preparation plan");
  check(Reject(()=>PreparationPolicy.ValidateOptions(null))&&Reject(()=>PreparationPolicy.ValidateOptions(new(){Apps=null!})),"Malformed null preparation profiles fail validation rather than reaching an installer");
  check(Reject(()=>PreparationPolicy.Validate(job,"other-sid")),"Preparation cannot run for a different Windows user");
  check(Reject(()=>PreparationPolicy.Validate(job with{Steps=job.Steps.Append(new(){Id="script",Kind="exec"}).ToList()},"test-sid")),"Persisted preparation cannot inject executable steps");
  var altered=job with{Steps=job.Steps.Select(s=>s with{}).ToList()};altered.Steps[0]=altered.Steps[0] with{Kind="powershell"};check(Reject(()=>PreparationPolicy.Validate(altered,"test-sid")),"Preparation validates the exact ordered step kinds");
  var backend=new FakePreparation();var saves=0;var engine=new PreparationEngine(backend,_=>saves++,()=>false);var boot=DateTimeOffset.UtcNow.AddMinutes(-10);job.Consented=DateTimeOffset.Now;await engine.RunAsync(job,boot,new Progress<string>());check(job.State=="complete"&&job.Steps.All(PreparationPolicy.Done)&&saves>job.Steps.Count,"Preparation executes selected steps and persists state transitions");
  var calls=backend.Calls.Count;await engine.RunAsync(job,boot,new Progress<string>());check(backend.Calls.Count==calls,"Completed preparation does not reinstall finished steps");
  var interrupted=PreparationPolicy.Create(new(){Apps=["firefox","vlc"]},"test-sid","x");interrupted.Consented=DateTimeOffset.Now;var fail=new FakePreparation{Fail="app-firefox"};await new PreparationEngine(fail,_=>{},()=>false).RunAsync(interrupted,boot,new Progress<string>());check(interrupted.State=="attention"&&interrupted.Steps.Single(s=>s.Id=="app-vlc").State=="done","One failed app does not prevent unrelated remaining installations and never reports full success");
  fail.Fail="";var oldCalls=fail.Calls.Count;await new PreparationEngine(fail,_=>{},()=>false).RunAsync(interrupted,boot,new Progress<string>());check(interrupted.State=="complete"&&fail.Calls.Count==oldCalls+2&&fail.Calls[^1]=="verify","Retry reruns the failed step and final verification without reinstalling completed apps");
  var noBackup=PreparationPolicy.Create(new(){Apps=["firefox"]},"test-sid","x");noBackup.Consented=DateTimeOffset.Now;var backupFail=new FakePreparation{Fail="backup"};await new PreparationEngine(backupFail,_=>{},()=>false).RunAsync(noBackup,boot,new Progress<string>());check(!backupFail.Calls.Contains("drivers")&&!backupFail.Calls.Contains("oem")&&backupFail.Calls.Contains("app-firefox"),"Backup failure blocks driver writes while allowing independent app tasks");
  var reboot=PreparationPolicy.Create(new(),"test-sid","x");reboot.Consented=DateTimeOffset.Now;var restart=new FakePreparation{Restart="drivers"};var run=new PreparationEngine(restart,_=>{},()=>false);await run.RunAsync(reboot,boot,new Progress<string>());check(reboot.State=="reboot"&&!restart.Calls.Contains("windows"),"Required reboot checkpoints the queue before later installers");var before=restart.Calls.Count;await run.RunAsync(reboot,boot,new Progress<string>());check(before==restart.Calls.Count,"Preparation refuses to continue reboot checkpoint in the same boot");restart.Restart="";await run.RunAsync(reboot,boot.AddHours(1),new Progress<string>());check(reboot.State=="complete"&&restart.Calls.Count(s=>s=="backup")==1,"After reboot preparation rescans driver/update stages and retains the existing backup");
  var paused=PreparationPolicy.Create(new(),"test-sid","x");paused.Consented=DateTimeOffset.Now;var idle=new FakePreparation();await new PreparationEngine(idle,_=>{},()=>true).RunAsync(paused,boot,new Progress<string>());check(paused.State=="paused"&&idle.Calls.Count==0,"Stop request pauses at a step boundary without starting an installer");
  var unapproved=PreparationPolicy.Create(new(),"test-sid","x");try{await engine.RunAsync(unapproved,boot,new Progress<string>());check(false,"Consent required");}catch(InvalidOperationException){check(true,"Preparation cannot install an unapproved plan");}
  PreparationStore.Save(paused);var roundtrip=PreparationStore.Load(paused.Id)!;PreparationPolicy.Validate(roundtrip,"test-sid");check(roundtrip.Id==paused.Id&&roundtrip.State=="paused"&&PreparationStore.Last()?.Id==paused.Id,"Durable preparation state survives an atomic save/reload");
  check(Reject(()=>PreparationStore.Folder("../outside")),"Preparation IDs cannot escape their local data directory");
  var script=PreparationWindows.Script(false);check(script.Contains("$installer.ForceQuiet=$true")&&script.Contains("RebootRequiredBeforeInstallation")&&script.Contains("IsInstalled=1")&&script.Contains("Preview|Önizleme"),"Windows installation checks reboot, avoids previews and verifies installed identities");check(script.Contains("Firmware|BIOS")&&script.Contains("3689BDC8-B205-4AF4-8D4A-A63924C5E9D5"),"Automatic Windows install excludes firmware and feature upgrade category");
  check(PreparationPolicy.PackageIds.All(id=>PreparationPackages.Definition(id).Id==id),"Every automatic package ID has a compiled-in installation definition");
  check(Reject(()=>PreparationPackages.Definition("app-community-arbitrary")),"Community manifests cannot provide elevated installer arguments");
  check(PreparationPackages.Definition("nvidia").Interactive&&PreparationPackages.Definition("amd").Interactive,"GPU helper UI requirements are explicit rather than guessed silent switches");
  var offline=Path.Combine(root,"usb-preparation");Directory.CreateDirectory(offline);await File.WriteAllTextAsync(Path.Combine(offline,"preparation-packages.json"),JsonSerializer.Serialize(new[]{new OfflinePreparationPackage("firefox","../escape.exe",new string('A',64),1024,"")}));check(Reject(()=>PreparationPackages.ReadOffline(offline)),"Offline installer manifests reject path traversal");
  await File.WriteAllTextAsync(Path.Combine(offline,"preparation-packages.json"),JsonSerializer.Serialize(new[]{new OfflinePreparationPackage("arbitrary","setup.exe",new string('A',64),1024,"")}));check(Reject(()=>PreparationPackages.ReadOffline(offline)),"Offline package import accepts only known signed installer recipes");
  var present=new InstalledApp("Mozilla Firefox (x64 tr)","156.0","Mozilla","","","Registry");check(PreparationPackages.Present("firefox",[present])&&!PreparationPackages.Present("prepare-chrome",[present]),"Install verification matches the selected product rather than any browser");
  foreach(var drivers in new[]{true,false}){var errors=await Commands.JsonAsync<string[]>("$tokens=$null;$errors=$null;[Management.Automation.Language.Parser]::ParseInput("+PackageSafety.QuotePs(PreparationWindows.Script(drivers,Path.Combine(root,"stop")))+",[ref]$tokens,[ref]$errors)|Out-Null;ConvertTo-Json -InputObject @($errors|ForEach-Object {$_.Message})");check(errors.Length==0,"Native Windows PowerShell parses preparation installation script without executing it: "+(drivers?"drivers":"Windows"));}
  var maxBoots=PreparationPolicy.Create(new(),"test-sid","x");maxBoots.Consented=DateTimeOffset.Now;maxBoots.Pass=4;maxBoots.State="reboot";maxBoots.BootTime=boot;var loop=new FakePreparation{Restart="drivers"};await new PreparationEngine(loop,_=>{},()=>false).RunAsync(maxBoots,boot.AddDays(1),new Progress<string>());check(maxBoots.State=="attention"&&maxBoots.Pass==4,"Repeated reboot requirements stop after four rounds rather than creating an endless startup loop");
 }
 private sealed class FakePreparation:IPreparationBackend
 {
  public List<string> Calls=[];public string Fail="",Restart="";
  public Task<PreparationOutcome> ExecuteAsync(PreparationJob job,PreparationStep step,IProgress<string> progress,CancellationToken token){Calls.Add(step.Id);if(step.Id==Fail)throw new IOException("simulated installer failure");return Task.FromResult(new PreparationOutcome("done","verified",step.Id==Restart));}
 }
}
